-- PRIVATE NBA GM DEVELOPMENT FIXTURE, sourced verbatim for ratings/identities from
-- docs/nba-gm-330-six-skills-PROVISIONAL-2026-10-29.json at foundation merge.
-- PROVISIONAL positions and entirely FICTIONAL game prices (not actual NBA contracts).
-- Do not convert this migration into a publicly readable player table.















do $$
begin
  if (select count(*) from private.nba_gm_dev_players) <> 330
    or (select count(distinct team_code) from private.nba_gm_dev_players) <> 30
    or exists (select 1 from private.nba_gm_dev_players where
